findings=[dict(id='restoration-literal-marker',kind='finding',run=run,category='defect',domain='code',summary='Literal dependency directories that match Kache dep-info sentinels are expanded into different paths, allowing Cargo and Make to miss real input changes.',scenario='Generated Rust bin paths __kache_cwd__/main.rs, __kache_workspace__/main.rs, __kache_root__/main.rs and __kache_target_rule__/main.rs each restored from cache. Existing decoy main.rs paths satisfy restore checks. After real source changes output 1→2, Cargo says Fresh and executable still prints 1. C++ includes __kache_root__/value.h; restored dep-info watches decoy value.h, so Make skips compile after actual header changes and program stays at 1.',evidence=[dict(path='crates/kache-store/src/link.rs',lines='1635-1638,1740-1777,2023-2080,2093-2148',point='Reserved marker strings are expanded in each Make token without an escape for original relative dependencies.'),dict(path='src/wrapper.rs',lines='2980-3015,5193-5206,5286-5293,5615-5624',point='C++ and Rust store/restore paths feed compiler dep-info through these transforms.'),dict(path='investigation/evidence/cwd-replay.log',lines='all',point='Actual runtime stale output after source change; stored JSON captures dep-info each stage.'),dict(path='investigation/evidence/cpp-marker-replay.log',lines='all',point='Actual stale C++ output after header change.')],trace='cargo build / make → baseline kache wrapper → store normalized compiler dep-info → cache hit → expand original literal marker into cwd/workspace/target → Cargo/Make watches existing wrong input → true input changes → build skips compilation → stale executable',authority=dict(source='compiler caching correctness',quote='Restoring a cache hit must preserve the compiler dependency set so a change to an actual input invalidates the build.'),proof=dict(red_test='FILE restoration-replay.py\n'+source('restoration-replay.py')+'\nFILE cpp-marker-replay.py\n'+source('cpp-marker-replay.py'),name='rust_marker(__kache_cwd__) and cpp_marker(__kache_root__)',fails_on=sha,output='AssertionError: RESTORATION_SOURCE_CHANGE_MISSED: literal __kache_cwd__ dependency changed but executable returned 1, expected 2\nAssertionError: CPP_HEADER_CHANGE_MISSED: literal __kache_root__ header changed but executable returned 1, expected 2',gate_cases=cases[:2]),severity='Silent stale output for legal literal names, reaching ordinary Cargo and Make cache hits. Existing matching decoy increases impact from conservative rebuild to missed rebuild. This is conditional on marker spelling; no claim about arbitrary paths.',status='open'),dict(id='restoration-shared-publication-permission',kind='finding',run=run,category='defect',domain='code',summary='Duplicate publication of a source already hardlinked to its published blob clears the existing blob read-only protection and allows mutation through the source alias.',scenario='On generated HFS+ filesystem, use baseline ArtifactStore public put_with_compile_time API with immutable .rlib output and a policy permitting hardlinks. First put links source and blob, mode 0444. Second put of the same source stages a third alias and detects existing blob; staging discard changes shared permissions to 0666. Writing source succeeds and changes blob bytes. No forced test hook was used. This condition is proved at exported store API; ordinary Cargo end-to-end entry into this exact duplicate-source state was not proved.',evidence=[dict(path='crates/kache-store/src/store.rs',lines='269-281,2784-2828,3901-3983,4024-4085',point='Staging hardlinks source on real no-CoW path. Existing-blob branch discards staging through unlink_blob, which clears readonly on the shared inode. publish returns before set_blob_readonly.'),dict(path='src/wrapper.rs',lines='4899-4911,5262-5270',point='Rust wrapper calls put_with_compile_time and retains ordinary compiler-owned paths for .rlib/.rmeta; source policy in src/compiler_store.rs permits immutable Hardlink kinds.'),dict(path='investigation/evidence/permissions-public-api.log',lines='all',point='Same source/blob inode 0444→0666; SOURCE_WRITE Ok(()); BLOB_CHANGED true; assertion fails.'),dict(path='investigation/evidence/permission-replay.log',lines='all',point='Generated HFS+ image mount and successful detach in finally.')],trace='public ArtifactStore.put_with_compile_time → stage_blob_from_source real hardlink → hash → publish_staged_blob → blob already exists → discard_staged_blob → unlink_blob clears shared readonly → blob stays writable → source write changes CAS bytes',authority=dict(source='published blob integrity',quote='A hardlinked published immutable blob must stay read-only so a consumer write cannot alter its recorded content.'),proof=dict(red_test='FILE permission-replay.py\n'+source('permission-replay.py')+'\nFILE permission-probe.rs\n'+source('permission-probe.rs')+'\nFILE restoration-replay.py\n'+source('restoration-replay.py'),name='duplicate_shared_blob_publication_keeps_readonly',fails_on=sha,output='PUBLISHED mode=444 source_inode matches blob inode\nAFTER_DUPLICATE mode=666\nSOURCE_WRITE Ok(()); BLOB_CHANGED true\nPUBLISHED_BLOB_BECAME_WRITABLE',gate_cases=cases[2:]),severity='Loss of CAS content integrity when an existing published blob/source shared inode is submitted again. Source alias becomes writable and can change bytes under recorded digest. Exported production store path executed; usual Cargo recurrence frequency and downstream cache-hit validation response remain unmeasured.',status='open')]
